let _minWidth;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 255);
  setObject();
}

let _aryLine = [];
function setObject() {
  _minWidth = max(width, height) * 1;
  strokeWeight(_minWidth/400);
  stroke(0);
  noFill();
  strokeCap(SQUARE);
  let numLine = 5;
  let yRatio = 0.6;
  for (let i = 0; i < numLine; i++) {
      let x = random(-_minWidth/3, _minWidth/3);
      let y = -_minWidth/2.5 + yRatio * _minWidth * (i / (numLine - 1))**1.5;
      let centXy = createVector(x, y);
      let r = 0.4/2 * _minWidth * ((i + 1) / (numLine))**1;
      let r_h = r;
      let r_v = r / 3;
      let initAng = 0;
      let totalAng = 2*PI;
      _aryLine[i] = new BendLine(centXy, r_h, r_v, initAng, totalAng);
  }
}

class BendLine {
  constructor(centXy, r_h, r_v, initAng, totalAng) {
    this.centXy = centXy;
    this.r_h = r_h;
    this.r_v = r_v;
    this.initAng = initAng;
    this.totalAng = totalAng
    this.numPoints = 100;
    let angStep = this.totalAng / this.numPoints;
    this.aryXy = [];
    for (let i = 0; i < this.numPoints; i++) {
      let ang = angStep * i;
      this.aryXy.push(createVector(this.r_v * cos(ang), this.r_h * sin(ang)));
    }
    this.numBend = 3;
    this.aryRParameter = [];
    for (let i = 0; i < this.numBend; i++) {
      this.aryRParameter[i] = [this.r_v / 30 * 0.8**i, random(2*PI), 2*PI / random(100, 500)];//[max, init, speed]
    }
    this.aryinitAngParameter = [];
    for (let i = 0; i < this.numBend; i++) {
      this.aryinitAngParameter[i] = [2*PI, random(2*PI), 2*PI / random(200, 1000)];//[max, init, speed]
    }
    this.aryAngStep = [];
    for (let i = 0; i < this.numBend; i++) {
      this.aryAngStep[i] = this.totalAng / this.numPoints * int(random(3, 8 + i) * 1);
    }
    this.aryColParameter = [
      [random(1000), random(1000), 1/1, 0.005],
      [random(1000), random(1000), 1/1, 0.005]];//[initNoiseX, initNoiseY, noiseR, noiseSpeed]
    this.numCycle = 5;

    this.trunkAmp = random(_minWidth / 10);
    this.trunkInitAng = random([0, PI]);
  }
  updateTrunk() {
    let rootXy = createVector(0, _minWidth / 2 * 0.9);
    let endXy = p5.Vector.add(this.centXy, p5.Vector.rotate(this.newAryXy[0], PI/2));
    let numPoints = 50;
    this.aryXyTrunk = [];
    for (let i = 0; i < numPoints; i++) {
      this.aryXyTrunk.push(p5.Vector.lerp(rootXy, endXy, 1 / (numPoints - 1) * i));
    }
    let vecSin = p5.Vector.sub(this.aryXyTrunk[this.aryXyTrunk.length-1], this.aryXyTrunk[0]).normalize().rotate(PI/2);
    for (let i = 0; i < this.aryXyTrunk.length; i++) {
      let ang = 2*PI / (this.aryXyTrunk.length - 1) * i;
      let ampVecSin = p5.Vector.mult(vecSin, sin(this.trunkInitAng + ang) * this.trunkAmp);
      this.aryXyTrunk[i] = p5.Vector.add(this.aryXyTrunk[i], ampVecSin);
    }
  }
  update() {
    this.updateR();
    this.updateInitAng();
    this.newAryXy = this.aryXy;
    for (let i = 0; i < this.numBend; i++) {
      this.newAryXy = bend(this.newAryXy, this.aryR[i], this.aryinitAng[i], this.aryAngStep[i], this.numCycle, "CLOSE");
    }
    this.updateTrunk();
  }
  updateR() {
    this.aryR = [];
    for (let i = 0; i < this.aryRParameter.length; i++) {
      this.aryR[i] = this.aryRParameter[i][0] * (sin(this.aryRParameter[i][1] + this.aryRParameter[i][2] * frameCount));
    }
  }
  updateInitAng() {
    this.aryinitAng = [];
    for (let i = 0; i < this.aryinitAngParameter.length; i++) {
      this.aryinitAng[i] = this.aryinitAngParameter[i][1] + this.aryinitAngParameter[i][0] * (sin(this.aryinitAngParameter[i][2] * frameCount));
    }
  }
  draw() {
    push();
    strokeWeight(this.r_h / 100);
    translate(this.centXy.x, this.centXy.y);
    rotate(PI/2);
    for (let i = 1; i < this.newAryXy.length; i++) {
      line(this.newAryXy[0].x, this.newAryXy[0].y, this.newAryXy[i].x, this.newAryXy[i].y)
    }
    pop();
  }
  drawTrunk() {
    push();
    strokeWeight(this.r_h / 100);
    beginShape();
    for (let i = 0; i < this.aryXyTrunk.length; i++) {
      vertex(this.aryXyTrunk[i].x, this.aryXyTrunk[i].y);
    }
    endShape();
    pop();
  }
}

function bend(aryXy, r, initAng, angStep, numCycle, mode) {
  let aryXy2 = aryXy;
  if (mode == "CLOSE") {
    for (let j = 0; j < numCycle; j++) {
      let aryXyNew = [];
      for (let i = 0; i < aryXy2.length; i++) {
        let xy_1_2 = p5.Vector.sub(aryXy2[(i+1)%aryXy2.length], aryXy2[i]);
        let ang = initAng + angStep * i;
        xy_1_2.rotate(-PI/2).setMag(r * sin(ang));
        let xy = p5.Vector.add(aryXy2[i], xy_1_2);
        aryXyNew.push(xy);
      }
      aryXy2 = aryXyNew;
    }
  } else { //open
    for (let j = 0; j < numCycle; j++) {
      let aryXyNew = [];
      for (let i = 0; i < aryXy2.length; i++) {
        let i1, i2;
        if (i == aryXy2.length - 1) {
          i1 = i - 1;
          i2 = i;
        } else {
          i1 = i;
          i2 = i + 1;
        }
        let xy_1_2 = p5.Vector.sub(aryXy2[i2], aryXy2[i1]);
        let ang = initAng + angStep * i;
        xy_1_2.rotate(-PI/2).setMag(r * sin(ang));
        let xy = p5.Vector.add(aryXy2[i], xy_1_2);
        aryXyNew.push(xy);
      }
      aryXy2 = aryXyNew;
    }
  }

  return aryXy2;
}

function draw() {
  background(100);
  translate(width/2, height/2);
  for (let i = 0; i < _aryLine.length; i++) {
    _aryLine[i].update();
    _aryLine[i].drawTrunk();
    _aryLine[i].draw();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  setObject();
}

